add_action( 'woocommerce_single_product_summary', 'perfectpixel_content_above_add_to_cart', 29 );

function perfectpixel_content_above_add_to_cart() {
	$categories = wp_parse_id_list( '{{above_atc_category_ids}}' );
	if ( $categories && ! has_term( $categories, 'product_cat', get_the_ID() ) ) {
		return;
	}
	echo '<p class="perfectpixel-above-atc" style="margin-bottom:1em;font-weight:600">' . wp_kses_post( '{{above_atc_text}}' ) . '</p>';
}
